Function Invoke-PrimeFactors() {
    <#
    .SYNOPSIS
    Calculate the prime factors of a given natural number.

    .DESCRIPTION
    Check if the number is divisible by 2. If it is, divide it by 2 and add 2 to the list of factors.
    If it is not, increment the number by 1 and check if it is divisible by 3. If it is, divide it by 3 and add 3 to the list of factors.

    .PARAMETER Number
    The number to factorize.

    .EXAMPLE
    Invoke-PrimeFactors -Number 12
    #>
    [CmdletBinding()]
    Param(
        [Int64]$Number
    )
    $i = 2
    $factors = @()
    while ($Number -gt 1) {
        if ($Number % $i -eq 0) {
            $Number = $Number / $i
            $factors += $i
        } else {
            $i++
        }
    }
    return $factors
}

test_code:
BeforeAll {
    . "./PrimeFactors.ps1"
}

Describe "Test Invoke-PrimeFactors.ps1" {
    It "no factors" {
        $got = Invoke-PrimeFactors -Number 1
        $want = @()

        $got | Should -BeExactly $want
    }

    It "prime number" {
        $got = Invoke-PrimeFactors -Number 2
        $want = @(2)

        $got | Should -BeExactly $want
    }

    It "another prime number" {
        $got = Invoke-PrimeFactors -Number 3
        $want = @(3)

        $got | Should -BeExactly $want
    }

    It "square of a prime" {
        $got = Invoke-PrimeFactors -Number 9
        $want = @(3, 3)

        $got | Should -BeExactly $want
    }

    It "product of the first prime" {
        $got = Invoke-PrimeFactors -Number 4
        $want = @(2, 2)

        $got | Should -BeExactly $want
    }

    It "cube of a prime" {
        $got = Invoke-PrimeFactors -Number 8
        $want = @(2, 2, 2)

        $got | Should -BeExactly $want
    }

    It "product of second prime" {
        $got = Invoke-PrimeFactors -Number 27
        $want = @(3, 3, 3)

        $got | Should -BeExactly $want
    }

    It "product of third prime" {
        $got = Invoke-PrimeFactors -Number 625
        $want = @(5, 5, 5, 5)

        $got | Should -BeExactly $want
    }

    It "product of first and second prime" {
        $got = Invoke-PrimeFactors -Number 6
        $want = @(2,3)

        $got | Should -BeExactly $want
    }

    It "product of primes and non-primes" {
        $got = Invoke-PrimeFactors -Number 12
        $want = @(2, 2, 3)

        $got | Should -BeExactly $want
    }

    It "product of primes" {
        $got = Invoke-PrimeFactors -Number 901255
        $want = @(5, 17, 23, 461)

        $got | Should -BeExactly $want
    }

    It "factors include a large prime" {
        $got = Invoke-PrimeFactors -Number 93819012551
        $want = @(11, 9539, 894119)

        $got | Should -BeExactly $want
    }
}
